-- GENERATED by tools/gen_args.py: every builtin of the original with wrong or missing arguments. Do not edit.

cr_args_fn = function()
end

-- (the actor the actor builtins get: in cr_flat, following the boxes, with the model costume)
cr_t_args_setup = function()
	MakeCurrentSet("cr_flat.set")
	CR_ARGS_ACTOR = LoadActor("cr_args")
	PutActorInSet(CR_ARGS_ACTOR, "cr_flat.set")
	PutActorAt(CR_ARGS_ACTOR, 0, 0, 0)
	SetActorFollowBoxes(CR_ARGS_ACTOR, TRUE)
	SetActorCostume(CR_ARGS_ACTOR, "cr_box.cos")
	cr_log("actor", type(CR_ARGS_ACTOR))
end
cr_test("args_setup", cr_t_args_setup)

-- (each builtin gets an actor of its own, and every call starts from the same state: the set, the actor at the
-- origin facing 0. Otherwise a call that breaks the shared actor makes the calls after it fail, and run.py blames them)
cr_args_for = function(name)
	if CR_ARGS_FOR ~= name then
		CR_ARGS_FOR = name
		if CR_ARGS_ACTOR then
			PutActorInSet(CR_ARGS_ACTOR, nil)
		end
		MakeCurrentSet("cr_flat.set")
		CR_ARGS_ACTOR = LoadActor("cr_args_" .. name)
		PutActorInSet(CR_ARGS_ACTOR, "cr_flat.set")
		SetActorFollowBoxes(CR_ARGS_ACTOR, TRUE)
		SetActorCostume(CR_ARGS_ACTOR, "cr_box.cos")
	end
	PutActorAt(CR_ARGS_ACTOR, 0, 0, 0)
	SetActorRot(CR_ARGS_ACTOR, 0, 0, 0)
end

-- (fresh handles for the families of tools/gen_args.py)
cr_args_font = function()
	return LockFont("cr_font.laf")
end
cr_args_text = function()
	return MakeTextObject("abc", { font = cr_args_font(), x = 10, y = 20 })
end
cr_args_prim = function()
	return DrawLine(1, 2, 30, 40, { color = MakeColor(1, 2, 3) })
end
cr_args_image = function()
	return GetImage("cr_obj.bm")
end
cr_args_obj = function()
	return NewObjectState(0, 1, "cr_obj.bm", nil, TRUE)
end
cr_args_color = function()
	return MakeColor(10, 20, 30)
end

